(()=>{const session=window.CCDeviceSession,query=document.querySelector('#query');if(!session||!query)return;const box=document.createElement('section');box.id='deviceReuse';const title=document.createElement('h2');title.textContent='自分の端末に関係する情報を探す';const note=document.createElement('p');note.textContent='質問で入力した情報から1項目を選んで検索できます。入力値は外部送信しません。検索結果は文字列の一致であり、影響の有無を判定するものではありません。';const choices=document.createElement('div');box.append(title,note,choices);query.closest('form').before(box);let applied=null;function render(){choices.replaceChildren();const data=session.get();if(!data){choices.textContent='端末情報は未入力、または削除済みです。質問画面で入力できます。';if(applied!==null&&query.value===applied){query.value='';query.dispatchEvent(new Event('input',{bubbles:true}));}applied=null;return;}for(const key of ['os','maker','model','version','device']){if(!data[key]||data[key]==='不明')continue;const button=document.createElement('button');button.type='button';button.textContent=data[key]+'で検索';button.onclick=()=>{if(!session.get())return;query.value=data[key];applied=query.value;query.dispatchEvent(new Event('input',{bubbles:true}));};choices.append(button);}}window.addEventListener('cc-device-profile',render);render();})();
